<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
$e=GreenPortalDatabase::env();$c=GreenPortalDatabase::connect($e,'guniversal_dbp','GUNIVERSAL');$q=$c->query("SELECT e.codempresa FROM empresa e JOIN empresa_migracao_config c ON c.codempresa=e.codempresa WHERE c.banco_novo='ggdamericana_dbp' LIMIT 1");$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row)throw new RuntimeException('Mapeamento Goodyear nao encontrado.');$u=$c->prepare("UPDATE empresa_migracao_config SET status_migracao='LEGAL_DOMINIOS_CONCLUIDA',sincronismo_ativo=0,atualizado_em=CURRENT_TIMESTAMP WHERE codempresa=:id");$u->execute(['id'=>(int)$row['codempresa']]);$check=$c->prepare("SELECT e.codigo,e.status,c.status_migracao,c.sincronismo_ativo FROM empresa e JOIN empresa_migracao_config c ON c.codempresa=e.codempresa WHERE e.codempresa=:id");$check->execute(['id'=>(int)$row['codempresa']]);echo json_encode(['ok'=>true,'resultado'=>$check->fetch(PDO::FETCH_ASSOC)],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;
